const puppeteer = require('puppeteer');

(async () => {
  const browser = await puppeteer.launch({ headless: false, defaultViewport: null, args: ['--start-maximized'] });
  const page = await browser.newPage();

  const projectUrl = 'https://labs.google/fx/pt/tools/flow/project/f55035b1-95be-426c-99c0-785d51f79385';
  console.log(`Navegando para ${projectUrl}...`);
  await page.goto(projectUrl, { waitUntil: 'networkidle2' });
  await page.waitForTimeout(3000);

  // Passo 1: Abrir menu do card 1
  console.log('Passo 1: Clicando em Mais opções no card 1...');
  await page.waitForSelector('button[aria-label*="Mais"], button[id^="radix-"]', { visible: true });
  const menuButtons = await page.$$('button[id^="radix-"]');
  if (menuButtons.length > 0) await menuButtons[0].click();
  await page.waitForTimeout(1000);

  // Passo 2 & 3: Baixar 1K no card 1
  console.log('Passo 2 e 3: Selecionando Baixar > 1K...');
  await page.evaluate(() => {
    const items = Array.from(document.querySelectorAll('div, button'));
    const baixarBtn = items.find(el => el.textContent && el.textContent.includes('Baixar'));
    if (baixarBtn) baixarBtn.dispatchEvent(new MouseEvent('mouseover', { bubbles: true }));
  });
  await page.waitForTimeout(800);
  await page.evaluate(() => {
    const options = Array.from(document.querySelectorAll('button, div'));
    const opt1k = options.find(el => el.textContent && el.textContent.includes('1K'));
    if (opt1k) opt1k.click();
  });
  await page.waitForTimeout(2000);

  // Passo 4 & 5: Card 2
  console.log('Passo 4 e 5: Baixando imagem do card 2...');
  const menuButtons2 = await page.$$('button[id^="radix-"]');
  if (menuButtons2.length > 1) await menuButtons2[1].click();
  await page.waitForTimeout(1000);
  await page.evaluate(() => {
    const options = Array.from(document.querySelectorAll('button, div'));
    const opt1k = options.find(el => el.textContent && el.textContent.includes('1K'));
    if (opt1k) opt1k.click();
  });
  await page.waitForTimeout(2000);

  // Passo 6: Visualizar imagem 3
  console.log('Passo 6: Expandindo visualizador de mídia...');
  const images = await page.$$('img');
  if (images.length > 2) await images[2].click();
  await page.waitForTimeout(2000);

  // Passo 7: Voltar
  console.log('Passo 7: Voltando para a galeria...');
  await page.evaluate(() => {
    const backBtn = Array.from(document.querySelectorAll('button')).find(el => el.textContent && el.textContent.includes('Voltar'));
    if (backBtn) backBtn.click();
  });
  await page.waitForTimeout(1500);

  // Passo 8 & 9: Card 3
  console.log('Passo 8 e 9: Baixando imagem do card 3...');
  const menuButtons3 = await page.$$('button[id^="radix-"]');
  if (menuButtons3.length > 2) await menuButtons3[2].click();
  await page.waitForTimeout(1000);
  await page.evaluate(() => {
    const options = Array.from(document.querySelectorAll('button, div'));
    const opt1k = options.find(el => el.textContent && el.textContent.includes('1K'));
    if (opt1k) opt1k.click();
  });
  await page.waitForTimeout(2000);

  console.log('Macro concluído com sucesso!');
  await browser.close();
})();

