const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: false });
  const context = await browser.newContext();
  const page = await context.newPage();

  const projectUrl = 'https://labs.google/fx/pt/tools/flow/project/f55035b1-95be-426c-99c0-785d51f79385';
  console.log(`Navegando para ${projectUrl}...`);
  await page.goto(projectUrl, { waitUntil: 'networkidle' });
  await page.waitForTimeout(3000);

  // Passo 1 a 3: Card 1
  console.log('Passo 1 a 3: Baixando imagem 1 (1K)...');
  const menuButtons = page.locator('button[id^="radix-"]');
  await menuButtons.nth(0).click();
  await page.waitForTimeout(800);
  await page.locator('text="Baixar"').first().hover();
  await page.waitForTimeout(500);
  await page.locator('text="1K"').first().click();
  await page.waitForTimeout(2000);

  // Passo 4 a 5: Card 2
  console.log('Passo 4 a 5: Baixando imagem 2 (1K)...');
  await menuButtons.nth(1).click();
  await page.waitForTimeout(800);
  await page.locator('text="1K"').first().click();
  await page.waitForTimeout(2000);

  // Passo 6: Expandir imagem 3
  console.log('Passo 6: Visualizando imagem em tela cheia...');
  const cardImages = page.locator('img');
  await cardImages.nth(2).click();
  await page.waitForTimeout(1500);

  // Passo 7: Botão Voltar
  console.log('Passo 7: Retornando à galeria...');
  await page.locator('button:has-text("Voltar")').click();
  await page.waitForTimeout(1000);

  // Passo 8 a 9: Card 3
  console.log('Passo 8 a 9: Baixando imagem 3 (1K)...');
  await menuButtons.nth(2).click();
  await page.waitForTimeout(800);
  await page.locator('text="1K"').first().click();
  await page.waitForTimeout(2000);

  console.log('Automação Playwright finalizada!');
  await browser.close();
})();
